"""Static portfolio. Content is maintained in data/projects.json and data/artworks.json."""
from pathlib import Path
from html import escape as e
import json
from experience import hero, contact, footer as experience_footer
R=Path(__file__).resolve().parent.parent
SITE='https://lucascasagrande.com'
P=json.loads((R/'data/projects.json').read_text(encoding='utf8')); A=json.loads((R/'data/artworks.json').read_text(encoding='utf8'))

def head(title,desc,path='/',image='/assets/artworks/newart_02_1920.webp'):
 image=SITE+image if image.startswith('/') else image
 return f'''<!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{e(title)} — Lucas Casagrande</title><meta name="description" content="{e(desc)}"><link rel="canonical" href="{SITE}{path}"><meta name="theme-color" content="#0b0c0b"><meta property="og:type" content="website"><meta property="og:title" content="{e(title)} — Lucas Casagrande"><meta property="og:description" content="{e(desc)}"><meta property="og:url" content="{SITE}{path}"><meta property="og:image" content="{image}"><meta name="twitter:card" content="summary_large_image"><link rel="icon" href="/favicon.svg" type="image/svg+xml"><link rel="manifest" href="/site.webmanifest"><link rel="preload" href="/assets/fonts/Syne-800.ttf" as="font" type="font/ttf" crossorigin><link rel="stylesheet" href="/assets/site.css"><link rel="stylesheet" href="/assets/experience.css?v=20261108"><script src="/assets/site.js" defer></script><script src="/assets/experience.js?v=20261108" defer></script></head><body><a class="skip" href="#main">Saltar al contenido</a>'''
def nav():
 return '''<header class="site-head"><a class="brand" href="/" aria-label="Lucas Casagrande, inicio"><span>LUCAS</span><span>CASAGRANDE<i>.</i></span></a><button class="nav-toggle" type="button" aria-expanded="false" aria-controls="site-nav">Menú +</button><nav class="nav-links" id="site-nav" aria-label="Navegación principal"><a href="/work/">Trabajo</a><a href="/artworks/">Artworks</a><a href="/#live">Visuales</a><a href="/#about">Perfil</a><a href="/prensa/">Prensa</a><a href="/#contact" class="contact-link">Hablemos ↗</a></nav></header>'''
def footer():
 return experience_footer()

def lightbox():
 return '''<div class="lightbox" role="dialog" aria-modal="true" aria-label="Obra ampliada" aria-hidden="true"><button type="button" class="lightbox-close" aria-label="Cerrar obra ampliada">×</button><img alt=""><p class="lightbox-title" aria-live="polite"></p><div class="lightbox-controls"><button type="button" data-prev aria-label="Obra anterior">←</button><button type="button" data-next aria-label="Obra siguiente">→</button></div></div>'''
def art(a,desc=False):
 return f'''<figure data-category="{e(a.get('series',a['category']))}"><button class="art-button" type="button" data-art="{a['image']}" data-title="{e(a['title'])}" aria-label="Ampliar {e(a['title'])}"><img src="{a.get('thumbnail',a['image'])}" alt="{e(a['description'])}" loading="lazy" width="{a.get('width',1000)}" height="{a.get('height',1000)}"></button><figcaption><div class="art-caption"><strong>{e(a['title'])}</strong><span>{e(a.get('series',a['category']))}</span></div>{'<p class="art-description">'+e(a['description'])+'</p>' if desc else ''}</figcaption></figure>'''
def work(p):
 return f'''<a class="work-tile" data-category="{e(p.get('category','Motion y CGI'))}" href="/work/{p['slug']}/"><div class="work-image"><img src="{p['img']}" alt="{e(p['title'])}: {e(p['sub'])}" loading="lazy" width="1600" height="900"><span class="work-open" aria-hidden="true">↗</span></div><div class="work-meta"><div><h3>{e(p['title'])}</h3><p>{e(p['sub'])}</p></div><span class="work-num">{p['num']}</span></div></a>'''

def filters(values, target):
 return '<div class="filter-bar shell" data-filter-for="'+target+'" role="group" aria-label="Filtrar selección"><button class="active" type="button" data-filter="all" aria-pressed="true">Todo</button>'+''.join('<button type="button" data-filter="'+e(v)+'" aria-pressed="false">'+e(v)+'</button>' for v in dict.fromkeys(values))+'</div>'

def video(v):
 local=v.get('local_video') or ('/assets/videos/'+v['vid']+'.mp4' if (R/'assets/videos'/(v['vid']+'.mp4')).exists() else None)
 attr='data-local-video="'+e(local)+'"' if local else 'data-vimeo="'+v['vid']+'"'
 return f'''<figure class="film"><div class="film-frame {'portrait' if v.get('portrait') else ''}"><button class="video-load" type="button" {attr} data-title="{e(v['title'])}" aria-label="Reproducir {e(v['title'])}"><img src="{v['img']}" alt="{e(v['title'])}" loading="lazy" width="1600" height="900"></button></div><figcaption><h3>{e(v['title'])}</h3><p>{e(v.get('description',''))}</p></figcaption></figure>'''

def case_sections(p):
 out=''
 for s in p.get('sections',[]):
  out+=f'''<section class="case-section shell" id="{e(s['id'])}"><div class="section-top"><div><p class="eyebrow">{e(s.get('label','Proyecto / En detalle'))}</p><h2>{e(s['title'])}</h2></div><p>{e(s.get('description',''))}</p></div>'''
  if s.get('videos'):out+='<div class="film-grid '+('portrait-grid' if all(v.get('portrait') for v in s['videos']) else '')+'">'+''.join(video(v) for v in s['videos'])+'</div>'
  if s.get('images'):
   out+='<div class="frames-grid">'+''.join(f'''<figure><button class="art-button" type="button" data-art="{im['image']}" data-title="{e(im.get('title','Styleframe'))}" aria-label="Ampliar {e(im.get('title','Styleframe'))}"><img src="{im['image']}" alt="{e(im.get('description',im.get('title','Styleframe')))}" loading="lazy" width="1600" height="900"></button><figcaption>{e(im.get('title',''))}</figcaption></figure>''' for im in s['images'])+'</div>'
  out+='</section>'
 return out
def write(path,content):
 p=R/path;p.parent.mkdir(parents=True,exist_ok=True);p.write_text(content,encoding='utf8')

featured=[next(x for x in P if x['slug']==s) for s in ['pandora','noorus-fill','lamicell-v22','continuous-reflection','toyota','snapdragon-pro']]
home=head('Dirección de arte, motion y mundos digitales','Lucas Casagrande. Director de arte, motion designer y artista 3D. Trabajo comercial, artworks, visuales y formación desde Buenos Aires para el mundo.')+nav()+f'''
<main id="main">
{hero(P)}
<div class="intro-index shell"><span>Buenos Aires, Argentina / Trabajo internacional</span><a href="#selected">01 — Trabajo</a><a href="/artworks/">02 — Artworks</a><a href="#live">03 — Visuales</a><span>Una selección en continuo movimiento</span></div>
<section class="section shell" id="selected"><div class="section-top"><div><p class="eyebrow">01 / Proyectos seleccionados</p><h2>Del concepto<br>a la <span class="italic">imagen.</span></h2></div><p>Una selección de proyectos donde la dirección visual se encuentra con el objeto, el movimiento y la experiencia.</p></div><div class="work-grid">{''.join(work(p) for p in featured)}</div><div class="section-end"><p>Más registros, lenguajes y maneras de resolver una idea.</p><a class="btn" href="/work/">Ver todos los proyectos</a></div></section>
<section class="section shell paper" id="artworks"><div class="section-top"><div><p class="eyebrow">02 / Artworks</p><h2>La búsqueda<br>también es <span class="italic">obra.</span></h2></div><p>Estudios de forma, materia, espacio y atmósfera. Obra, exploración y desarrollo visual a través de distintos proyectos.</p></div><div class="art-preview">{''.join(art(a) for a in [next(a for a in A if a['slug']==s) for s in ['art-04','art-12','art-07']])}</div><div class="section-end"><p>Escultura digital, paisajes posibles y mundos propios.</p><a class="btn" href="/artworks/">Entrar a la galería</a></div></section>
<section class="live shell" id="live"><div class="section-top"><div><p class="eyebrow">03 / Visuales, música y espacio</p><h2>La imagen<br>toma <span class="italic">el lugar.</span></h2></div><p>Del render a una pantalla de gran escala. El trabajo visual también puede habitar un escenario, una instalación o una sala.</p></div><div class="live-pair"><figure><img src="/assets/artworks/stage-mockup.webp" alt="Visualización conceptual de una obra de Lucas en pantalla LED de escenario" loading="lazy" width="1672" height="941"><figcaption class="mock-caption"><span>Artworks / Pantalla y visuales</span><span class="mock-tag">Visualización / mockup</span></figcaption></figure><figure><img src="/assets/artworks/gallery-mockup.webp" alt="Visualización conceptual de una obra de Lucas en una galería" loading="lazy" width="1672" height="941"><figcaption class="mock-caption"><span>Artworks / Escala de exposición</span><span class="mock-tag">Visualización / mockup</span></figcaption></figure></div><div class="reference-strip"><span>Referencias de trabajo<br>en música y eventos</span><span class="ref-logo cream"><img src="/assets/logos/creamfields.svg" alt="Creamfields" loading="lazy" width="210" height="65"></span><span class="ref-logo"><img src="/assets/logos/ultra.png" alt="Ultra Music Festival" loading="lazy" width="210" height="65"></span><strong>PopUp</strong></div></section>
<section class="about section shell" id="about"><figure class="about-image"><img src="/assets/portraits/lucas-editorial-01.webp" alt="Retrato editorial en blanco y negro de Lucas Casagrande" loading="lazy" width="1122" height="1402"><figcaption>Lucas Casagrande / Director de arte y motion designer</figcaption><div class="portrait-series"><img src="/assets/portraits/lucas-editorial-02.webp" alt="Retrato de Lucas con un acento de luz lima" loading="lazy" width="1122" height="1402"><img src="/assets/portraits/lucas-editorial-03.webp" alt="Retrato editorial de Lucas sobre fondo claro" loading="lazy" width="1122" height="1402"></div><p class="portrait-note">Serie editorial / Retratos con IA a partir de una fotografía original.</p></figure><div class="about-copy"><p class="eyebrow">El recorrido detrás de la imagen</p><h2>El oficio antes<br>que la <span class="italic">herramienta.</span></h2><p class="about-lead">Más de quince años explorando cómo una idea se convierte en una imagen que se siente.</p><p class="about-body">Mi recorrido pasa por estudios, agencias, televisión y proyectos internacionales. Incluye Argentina, Bahréin y Shanghai, con trabajo en Memac Ogilvy, JL Design y MPC. Hoy conecto dirección de arte, motion, 3D e inteligencia artificial desde Buenos Aires.</p><p class="about-body">La experimentación siempre estuvo ahí: en los primeros reels, en los visuales y en las piezas personales. La IA suma herramientas a esa búsqueda. El criterio para elegir, dirigir y terminar una pieza sigue siendo el centro.</p><div class="timeline"><div class="timeline-row"><span>Pause Fest</span><p><a href="https://www.pauseoriginals.com/" target="_blank" rel="noopener">Eternal Loop ↗</a> integra Pause Originals, la colección oficial de obras del festival.</p></div><div class="timeline-row"><span>Morcreate / 2020</span><p>Dos films para <a href="/work/continuous-reflection/">Continuous Refle(a)ction 2.0 ↗</a>, exposición online de ecoarte.</p></div><div class="timeline-row"><span>Ciudad Emergente / 2012</span><p>Participé en la sección Arte Digital del festival, en el Centro Cultural Recoleta, con mi productora Elfato.</p></div><div class="timeline-row"><span>Visuales / VJ</span><p>Trabajos vinculados a Creamfields, UMF y PopUp. La imagen como parte de una experiencia en vivo.</p></div><div class="timeline-row"><span>Compartir oficio</span><p>Dicté un curso de VJ en el CCK y fui docente en Domestika.</p></div><div class="timeline-row"><span>Hoy</span><p>Fundador y director creativo de CHIMICHURRI. Dirección visual, producción y formación para equipos.</p></div></div><div class="actions"><a class="btn" href="https://www.linkedin.com/in/lucascasagrande/" target="_blank" rel="noopener">Más sobre mi recorrido</a></div></div></section>
<section class="shell"><p class="eyebrow">Trabajemos juntos</p><div class="offer-row"><div class="offer"><h3>Una pieza. Un sistema.<br>Una dirección visual.</h3><p>Dirección de arte, motion y 3D para equipos que necesitan llevar una idea de la primera referencia a una entrega con identidad.</p><a href="/contacto/">Contame tu proyecto ↗</a></div><div class="offer"><h3>Aprender desde<br>el trabajo real.</h3><p>Charlas y talleres sobre creatividad, producción visual e IA aplicada para organizaciones y equipos. Un enfoque construido desde la práctica.</p><a href="/contacto/">Conversemos sobre capacitación ↗</a></div></div></section>
</main>{lightbox()}'''+footer()
banner='''<section class="visual-break"><img src="/assets/presentations/energia.webp" alt="" loading="lazy" width="1672" height="941"><div class="shell"><p class="eyebrow">Luz / Materia / Experimento</p><h2>Una imagen.<br>Un mundo <em>posible.</em></h2><a class="btn" href="/artworks/">Recorrer el archivo</a></div></section>'''
home=home.replace('<section class="section shell paper" id="artworks">',banner+'<section class="section shell paper" id="artworks">')
home=home.replace('</main>', '''<section class="press-teaser shell"><p class="eyebrow">Prensa / Charlas / Formación</p><div><h2>Ideas para compartir.</h2><p>Perfil, selección de trabajo y material para entrevistas, conferencias y equipos.</p><a class="btn" href="/prensa/">Ver press kit y catálogos</a></div></section></main>''',1)
home=home.replace('</main>',contact()+'</main>',1)
write('index.html',home)

artpage=head('Artworks / Archivo visual','Escultura digital, paisajes, materia y mundos propios. Una selección del archivo visual de Lucas Casagrande.','/artworks/')+nav()+f'''<main id="main"><header class="gallery-head shell"><p class="eyebrow">Artworks / Archivo visual</p><h1>Archivo<br><span class="italic">visual.</span></h1><p>Estudios y piezas que recorren distintos lenguajes: escultura digital, arquitectura, paisajes, materia orgánica y personajes. Imágenes del archivo que permiten seguir una búsqueda visual a través de proyectos y exploraciones.</p></header><section class="art-grid shell" aria-label="Galería de artworks">{''.join(art(a,True) for a in A)}</section><section class="shell"><div class="archive-link"><p>¿Una de estas imágenes te dispara una idea?</p><a class="btn primary" href="mailto:lucas.g.casagrande@gmail.com?subject=Artworks%20y%20visuales">Hablemos de visuales</a></div></section></main>{lightbox()}'''+footer()
artpage=artpage.replace('<section class="art-grid shell"',filters([a.get('series',a['category']) for a in A],'art-grid')+'<p class="selection-count shell">'+str(len(A))+' imágenes / Archivo de obra</p><section class="art-grid shell" id="art-grid"')
artpage=artpage.replace('¿Una de estas imágenes te dispara una idea?','Llevate la selección de obra.').replace('<a class="btn primary" href="mailto:lucas.g.casagrande@gmail.com?subject=Artworks%20y%20visuales">Hablemos de visuales</a>','<div class="actions"><a class="btn" href="/assets/press/Lucas_Casagrande_Artworks_2026_Horizontal.pdf" download>Catálogo horizontal</a><a class="btn" href="/assets/press/Lucas_Casagrande_Artworks_2026_Vertical.pdf" download>Catálogo vertical</a></div>')
write('artworks/index.html',artpage)

for i,p in enumerate(P):
 prev=P[(i-1)%len(P)];nxt=P[(i+1)%len(P)]
 if p.get('vid'):
  local=p.get('local_video') or ('/assets/videos/'+p['vid']+'.mp4' if (R/'assets/videos'/(p['vid']+'.mp4')).exists() else None)
  attr='data-local-video="'+e(local)+'"' if local else 'data-vimeo="'+p['vid']+'"'
  media=f'''<button class="video-load" type="button" {attr} data-title="{e(p['title'])}" aria-label="Reproducir {e(p['title'])}"><img src="{p['img']}" alt="Imagen de {e(p['title'])}" loading="eager" width="1600" height="900"></button>'''
 else:media=f'''<img src="{p['img']}" alt="Imagen de {e(p['title'])}" width="1600" height="900">'''
 infos=[('Enfoque',' / '.join(p['tags']))]
 if p.get('role'):infos.append(('Participación',p['role']))
 if p.get('studio'):infos.append(('Estudio / Agencia',p['studio']))
 if p.get('duration'):infos.append(('Duración',str(p['duration'])+' s'))
 if p.get('video_label'):infos.append(('Versión',p['video_label']))
 if p.get('year'):infos.append(('Año',p['year']))
 inf=''.join(f'<dt>{e(k)}</dt><dd>{e(v)}</dd>' for k,v in infos)
 links=[]
 for s in p.get('sources',[]):
  if 'behance.net/gallery/' in s['url'] or 'domestika.org/' in s['url']:
   links.append('<a href="'+e(s['url'])+'" target="_blank" rel="noopener">'+('Ver caso en Behance' if 'behance.net' in s['url'] else 'Ver proyecto del autor')+' ↗</a>')
 if links:inf+='<dt>Sobre el proyecto</dt><dd class="case-source-links">'+''.join(dict.fromkeys(links))+'</dd>'
 cta=f'<a class="btn primary" href="https://vimeo.com/{p["vid"]}" target="_blank" rel="noopener">Ver pieza en Vimeo</a>' if p.get('vid') else ''
 page=head(p['title'],p['sub']+'. '+p['body'],'/work/'+p['slug']+'/',p['img'])+nav()+f'''<main id="main"><header class="case-head shell"><p class="eyebrow">Trabajo / {p['num']}</p><h1 class="{'long-title' if len(p['title'])>25 else ''}">{e(p['title'])}</h1><p class="case-sub">{e(p['sub'])}</p><p class="case-tags">{''.join('<span>'+e(t)+'</span>' for t in p['tags'])}</p></header><section class="case-media" aria-label="Pieza audiovisual">{media}</section><section class="case-body shell"><div><p class="lead">{e(p['body'])}</p><p class="focus">{e(p['focus'])}</p><div class="actions">{cta}<a class="btn" href="/contacto/">Hablemos de un proyecto</a></div></div><aside class="case-info"><dl>{inf}</dl></aside></section><nav class="case-pager shell" aria-label="Más proyectos"><a href="/work/{prev['slug']}/"><small>← Proyecto anterior</small><strong>{e(prev['title'])}</strong></a><a href="/work/{nxt['slug']}/"><small>Proyecto siguiente →</small><strong>{e(nxt['title'])}</strong></a></nav></main>'''+footer()
 page=page.replace('<nav class="case-pager',case_sections(p)+'<nav class="case-pager',1)
 if p.get('sections'):
  anchors='<nav class="case-anchors shell" aria-label="Contenido del proyecto">'+''.join('<a href="#'+e(s['id'])+'">'+e(s.get('nav',s['title']))+' <span>↘</span></a>' for s in p['sections'])+'</nav>'
  page=page.replace('<section class="case-media"',anchors+'<section class="case-media"',1)
  page=page.replace('</main>',lightbox()+'</main>',1)
 write('work/'+p['slug']+'/index.html',page)
allpage=head('Trabajo / Selección de proyectos','Una selección de proyectos de motion, CGI, 3D e identidad audiovisual de Lucas Casagrande.','/work/')+nav()+f'''<main id="main"><header class="gallery-head shell"><p class="eyebrow">Trabajo / Una selección del recorrido</p><h1>Ideas que<br><span class="italic">tomaron forma.</span></h1><p>Proyectos, piezas y lenguajes visuales. Una selección de mi trabajo entre el objeto, el espacio y la imagen en movimiento.</p></header><section class="all-grid shell" aria-label="Todos los proyectos">{''.join(work(p) for p in P)}</section></main>'''+footer()
allpage=allpage.replace('<section class="all-grid shell"',filters([p.get('category','Motion y CGI') for p in P],'project-grid')+'<p class="selection-count shell">'+str(len(P))+' proyectos / Selección del portfolio</p><section class="all-grid shell" id="project-grid"')
write('work/index.html',allpage)

press=head('Prensa y presentaciones','Perfil de Lucas Casagrande, press kit, catálogos de obra y propuestas de charlas y formación.','/prensa/')+nav()+'''<main id="main"><header class="gallery-head shell"><p class="eyebrow">Prensa / Charlas / Equipos</p><h1>El oficio.<br><span class="italic">Las ideas.</span></h1><p>Material para conocer mi recorrido, recorrer el trabajo y abrir una conversación sobre creatividad, producción visual e inteligencia artificial.</p></header><section class="press-intro shell"><figure><img src="/assets/portraits/lucas-editorial-01.webp" alt="Retrato editorial de Lucas Casagrande" width="1122" height="1402"><figcaption class="portrait-note">Retrato editorial con IA a partir de una fotografía original.</figcaption></figure><div><p class="eyebrow">Lucas Casagrande</p><h2>Dirección de arte,<br>motion y 3D.</h2><p>Desde 2009 trabajo en producción creativa para estudios, agencias y televisión. Mi recorrido conecta Argentina, Bahréin y Shanghai, proyectos comerciales y exploración personal.</p><p>Fui docente en Domestika y fundé CHIMICHURRI, donde integro dirección visual, producción e inteligencia artificial. El foco está en construir imágenes con identidad y procesos que permitan llevarlas a término.</p><p>Mi obra Eternal Loop integra el archivo oficial Pause Originals. En 2020 participé con dos films en la exposición online de ecoarte Continuous Refle(a)ction 2.0, de Morcreate.</p><a class="btn" href="/contacto/">Contacto de prensa</a></div></section><section class="section shell"><div class="section-top"><div><p class="eyebrow">Material descargable</p><h2>Para llevar.</h2></div><p>Dos formatos para cada selección: horizontal para pantalla y vertical para lectura en el teléfono.</p></div><div class="download-grid"><article class="download-card"><img src="/assets/press/press-cover.jpg" alt="Portada del press kit de Lucas Casagrande" loading="lazy" width="960" height="540"><div><p class="eyebrow">Perfil / Trabajo / Charlas</p><h3>Press kit</h3><p>Biografía, recorrido visual y temas de conversación.</p><div class="download-links"><a href="/assets/press/Lucas_Casagrande_Press_Kit_2026_Horizontal.pdf" download>Horizontal / PDF ↗</a><a href="/assets/press/Lucas_Casagrande_Press_Kit_2026_Vertical.pdf" download>Vertical / PDF ↗</a></div></div></article><article class="download-card"><img src="/assets/press/artwork-cover.jpg" alt="Portada de la selección de obra de Lucas Casagrande" loading="lazy" width="1800" height="900"><div><p class="eyebrow">Artworks / Archivo visual</p><h3>Selección de obra</h3><p>Escultura digital, paisajes, mundos y estudios de material.</p><div class="download-links"><a href="/assets/press/Lucas_Casagrande_Artworks_2026_Horizontal.pdf" download>Horizontal / PDF ↗</a><a href="/assets/press/Lucas_Casagrande_Artworks_2026_Vertical.pdf" download>Vertical / PDF ↗</a></div></div></article></div></section><section class="talks shell"><p class="eyebrow">Charlas y talleres</p><h2>Compartir lo<br>que hacemos.</h2><div class="talk-row"><span>01</span><h3>De la pieza al sistema</h3><p>Dirección de arte, referencias y coherencia visual en procesos con IA.</p></div><div class="talk-row"><span>02</span><h3>Una agencia con agentes</h3><p>Experiencias de trabajo, reparto de tareas y revisión humana.</p></div><div class="talk-row"><span>03</span><h3>Del brief a la imagen</h3><p>Un taller práctico sobre concepto, producción, selección y entrega.</p></div><p class="talk-note">El contenido y el alcance se adaptan a cada equipo e institución.</p></section></main>'''+footer()
write('prensa/index.html',press)

contact_page=head('Contacto','Contame tu proyecto. Dirección de arte, motion, 3D y experiencias visuales.','/contacto/')+nav()+'<main id="main"><header class="contact-page-head shell"><p class="eyebrow">Contacto / Nuevas conexiones</p><h1>Hagamos algo<br><em>que se sienta.</em></h1></header>'+contact()+'</main>'+footer()
